"""Rust code generator (minimal stub; expand per plan 2)."""

from __future__ import annotations

from pathlib import Path

from bps.ast import ResolvedSchema


def emit_rust(resolved: ResolvedSchema, out_dir: Path) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    lib = out_dir / "src" / "lib.rs"
    lib.parent.mkdir(parents=True, exist_ok=True)
    lib.write_text(
        "// Generated by bpsc emit rust — expand with full encoding/packet emitters.\n"
        f"pub const PROTOCOL_ID: i32 = {resolved.protocols[next(iter(resolved.protocols))].protocol_id if resolved.protocols else 0};\n",
        encoding="utf-8",
    )
    (out_dir / "Cargo.toml").write_text(
        '[package]\nname = "bps_generated"\nversion = "0.1.0"\nedition = "2021"\n',
        encoding="utf-8",
    )
